package com.tradingsimulator.validationandportfolio;
import com.tradingsimulator.model.*; import java.math.BigDecimal;
public final class ValidationChain { public void validate(Order o, BigDecimal cash, int position, BigDecimal marketPrice){ if(o.side()==OrderSide.BUY && cash.compareTo(marketPrice.multiply(BigDecimal.valueOf(o.quantity())))<0) throw new IllegalArgumentException("Insufficient balance"); if(o.side()==OrderSide.SELL && position<o.quantity()) throw new IllegalArgumentException("Insufficient position"); if(o.quantity()>1_000_000) throw new IllegalArgumentException("Quantity exceeds position limit"); if(marketPrice.signum()<=0) throw new IllegalArgumentException("Price must be positive"); } public static ValidationChain defaultChain(){return new ValidationChain();} }
